1	#!/usr/bin/env node
2	// Differential test runner: compares /output/test2.mjs against the Python executable.
3	// Usage: node difftest.mjs [corpus.json ...]   (each file = JSON array of markdown source strings)
4	import { py, js } from './py.mjs';
5	import { readFileSync, readdirSync } from 'node:fs';
6	import { join } from 'node:path';
7	
8	const files = process.argv.slice(2);
9	let cases = [];
10	if (files.length === 0) {
11	  const dir = '/workspace/harness/corpus';
12	  for (const f of readdirSync(dir).sort()) {
13	    if (f.endsWith('.json')) {
14	      for (const c of JSON.parse(readFileSync(join(dir, f), 'utf8'))) cases.push({ src: c, file: f });
15	    }
16	  }
17	} else {
18	  for (const f of files) for (const c of JSON.parse(readFileSync(f, 'utf8'))) cases.push({ src: c, file: f });
19	}
20	
21	let pass = 0;
22	const fails = [];
23	for (const { src, file } of cases) {
24	  const a = py(src);
25	  const b = js(src);
26	  if (a.stdout === b.stdout && a.code === b.code) pass++;
27	  else fails.push({ file, src, expected: a.stdout, actual: b.stdout, ec: a.code, ac: b.code, stderr: b.stderr });
28	}
29	
30	const showN = Number(process.env.SHOW || 12);
31	for (const f of fails.slice(0, showN)) {
32	  console.log('======== FAIL [' + f.file + '] input=' + JSON.stringify(f.src));
33	  console.log('-- expected(rc=' + f.ec + '): ' + JSON.stringify(f.expected));
34	  console.log('-- actual  (rc=' + f.ac + '): ' + JSON.stringify(f.actual));
35	  if (f.stderr) console.log('-- stderr: ' + f.stderr.split('\n').slice(0, 6).join('\n'));
36	}
37	console.log('\n==== ' + pass + '/' + cases.length + ' passed, ' + fails.length + ' failed');
38	process.exit(fails.length ? 1 : 0);
